use super::{BODY,MAXIMUM,close_projection,close_source,denied,drain,driver,exact,paid,source,turns,with_bank};
use super::super::FemMaterial;
use super::super::NATIVE_MATERIAL_DIMENSION;
use semio_framework_value::{DslValue, ToValue, OriginalRetirementFailure, ValueError, retained_clone::{RetainedCloneStep, RetainedCloneRef}};
use semio_framework_value_snapshot_projection::snapshot_projection::ProjectionField;
use semio_framework_value::shared_issuance::{SealedShared, SharedIssuer};
use semio_framework_value_native_owned::{native_decoding::NativeReceive, owned::NativeReceiver};
use semio_framework_value_persistent::{list::persistent::PersistentList, list::persistent::PersistentSplice, list::persistent::PersistentSpliceKind, list::persistent::PersistentSet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
type Table=PersistentList<FemMaterial>;
fn expected(count:usize,prefix:&str)->serde_json::Value{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let row=&f["accepted"].as_array().unwrap().iter().find(|c|c["dimension"].as_u64()==Some(NATIVE_MATERIAL_DIMENSION as u64)).unwrap()["row"];serde_json::Value::Array((0..count).map(|i|{let mut r=row.clone();r["id"]=format!("material-{i}").into();r["name"]=format!("{prefix}{i}").into();r}).collect())}
fn received_table(count:usize)->Table{received_table_value(expected(count,"Material α🙂 "))}
fn received_table_value(value:serde_json::Value)->Table{let original=source(DslValue::from(&value));let mut receiver=<Table as NativeReceive<DslValue>>::receiver();let root=with_bank(|bank|driver::receive_cut(&mut receiver,original.borrow(),bank,BODY,None)).unwrap().expect("uncut receive publishes");with_bank(|bank|driver::close(&mut receiver,bank,BODY));assert!(receiver.terminal_is_empty());drop(receiver);close_source(original);root}
fn sealed_original(row:RetainedCloneRef<'_,FemMaterial>)->SealedShared<FemMaterial>{
 let mut field=ProjectionField::<FemMaterial>::default();
 while !field.ready(){let d=field.demands(row,BODY,MAXIMUM).unwrap();let work=field.advance_work_demand(row,BODY,MAXIMUM).unwrap();paid::<OriginalRetirementFailure>(d,work,&mut|effect,reply,recover|if recover{field.recover_advance_into(row,BODY,MAXIMUM,effect,reply)}else{field.advance_into(row,BODY,MAXIMUM,effect,reply)});}
 let mut value=None;let d=field.take_output_demand().unwrap();paid::<ValueError>(d,1,&mut|effect,reply,recover|if recover{field.recover_take_output_into(&mut value,effect,reply)}else{field.take_output_into(&mut value,effect,reply)});
 close_projection(field);
 let mut input=value;let mut output=None;let d=semio_framework_value_native_owned::native_decoding::NativeOwnedDecodeControl::shared_birth_demand::<FemMaterial>();
 with_bank(|bank|{let(outcome,_,_)=driver::funded(bank,exact(d),MAXIMUM,|effect|SealedShared::admit_from(&mut input,SharedIssuer::owned(),&mut output,effect));outcome.result.unwrap_or_else(|_|panic!("actual Material original inverse row birth"));});
 output.expect("sealed Material original")
}
fn splice(original:RetainedCloneRef<'_,Table>,authored:Option<RetainedCloneRef<'_,SealedShared<FemMaterial>>>,kind:PersistentSpliceKind,index:usize,cut:Option<usize>)->Option<Table>{
 let mut cursor=PersistentSplice::new(kind,index);let mut turns=0;let mut ready=false;
 while !ready&&cut.is_none_or(|cut|turns<cut){let d=cursor.demand(original,authored).unwrap();let work=cursor.advance_work_demand(original,authored).unwrap();let step=paid::<ValueError>(d,work,&mut|effect,reply,recover|if recover{Ok(reply.pending())}else{cursor.advance_into(original,authored,effect,reply)});ready=matches!(step,RetainedCloneStep::Complete(_));turns+=1;}
 let mut output=None;if ready{let d=cursor.take_demand();let work=cursor.take_work_demand();paid::<ValueError>(d,work,&mut|effect,reply,recover|if recover{Ok(reply.pending())}else{cursor.take_into(&mut output,effect,reply)});}
 with_bank(|bank|{let g=exact(cursor.begin_close_demand());driver::funded(bank,g,cursor.begin_close_work_demand().max(1),|effect|cursor.begin_close_paid(effect)).0.result.unwrap_or_else(|_|panic!("splice close start"));});
 while !cursor.terminal_is_empty(){let d=cursor.close_demand(BODY).unwrap();let work=cursor.close_work_demand(BODY).unwrap();paid::<OriginalRetirementFailure>(d,work,&mut|effect,reply,recover|if recover{cursor.recover_close_into(BODY,effect,reply)}else{cursor.close_into(BODY,effect,reply)});}
 let(_,h)=observe(||drop(cursor));assert_eq!(h,(0,0));output
}
fn set(original:RetainedCloneRef<'_,Table>,authored:RetainedCloneRef<'_,SealedShared<FemMaterial>>,index:usize,cut:Option<usize>)->Option<Table>{
 let mut cursor=PersistentSet::new(index);let mut turns=0;
 while !cursor.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=cursor.demand(original,authored).unwrap();let work=cursor.advance_work_demand(original,authored).unwrap();paid::<ValueError>(d,work,&mut|effect,reply,recover|if recover{Ok(reply.pending())}else{cursor.advance_into(original,authored,effect,reply)});turns+=1;}
 let mut output=None;if cursor.output_ready(){let d=cursor.take_demand().unwrap();let work=cursor.take_work_demand().unwrap();paid::<ValueError>(d,work,&mut|effect,reply,recover|if recover{Ok(reply.pending())}else{cursor.take_into(&mut output,effect,reply)});}
 with_bank(|bank|{let g=exact(cursor.begin_close_demand());driver::funded(bank,g,cursor.begin_close_work_demand().max(1),|effect|cursor.begin_close_paid(effect)).0.result.unwrap_or_else(|_|panic!("set close start"));});
 while !cursor.terminal_is_empty(){let d=cursor.close_demand(BODY).unwrap();let work=cursor.close_work_demand(BODY).unwrap();paid::<OriginalRetirementFailure>(d,work,&mut|effect,reply,recover|if recover{cursor.recover_close_into(BODY,effect,reply)}else{cursor.close_into(BODY,effect,reply)});}
 let(_,h)=observe(||drop(cursor));assert_eq!(h,(0,0));output
}
#[test]
fn native_material_ranked_insert_remove_set_and_inverse_preserve_original_rows(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for case in f["structural"].as_array().unwrap(){let count=case["count"].as_u64().unwrap()as usize;let index=case["index"].as_u64().unwrap()as usize;let kind=case["kind"].as_str().unwrap();for cut in std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let original=source(received_table(count));let mut authored=expected(1,"Authored α🙂 ");authored[0]["id"]=if kind=="set"{format!("material-{index}")}else{"material-authored".to_owned()}.into();authored[0]["e"]=215000000000_f64.into();let authored_table=source(received_table_value(authored));let native=sealed_original(authored_table.borrow().project(0,|table|table.get(0).unwrap()));let native=source(native);let output=if kind=="set"{set(original.borrow(),native.borrow(),index,cut)}else{splice(original.borrow(),(kind=="insert").then(||native.borrow()),if kind=="insert"{PersistentSpliceKind::Insert}else{PersistentSpliceKind::Remove},index,cut)};
 if let Some(output)=output{let output=source(output);let mut ids:Vec<_>=(0..count).map(|i|format!("material-{i}")).collect();match kind{"insert"=>ids.insert(index,"material-authored".into()),"remove"=>{ids.remove(index);},"set"=>ids[index]=format!("material-{index}"),_=>panic!("declared Material structural kind")};assert_eq!(output.borrow().get().len(),ids.len());for(i,id)in ids.iter().enumerate(){assert_eq!(output.borrow().get().get(i).unwrap().id.as_str(),id);let previous=if kind=="insert"{(i!=index).then(||i-usize::from(i>index))}else if kind=="remove"{Some(i+usize::from(i>=index))}else{(i!=index).then_some(i)};if let Some(previous)=previous{assert!(std::ptr::eq(output.borrow().get().get(i).unwrap(),original.borrow().get().get(previous).unwrap()));}}
  let inverse=if kind=="insert"{splice(output.borrow(),None,PersistentSpliceKind::Remove,index,None).unwrap()}else{let removed=sealed_original(original.borrow().project(index,move|table|table.get(index).unwrap()));let removed=source(removed);let result=if kind=="set"{set(output.borrow(),removed.borrow(),index,None).unwrap()}else{splice(output.borrow(),Some(removed.borrow()),PersistentSpliceKind::Insert,index,None).unwrap()};close_source(removed);result};assert_eq!(&inverse,original.borrow().get());for i in 0..count{assert!(std::ptr::eq(inverse.get(i).unwrap().id.get(),original.borrow().get().get(i).unwrap().id.get()));assert!(std::ptr::eq(inverse.get(i).unwrap().name.get(),original.borrow().get().get(i).unwrap().name.get()));}drain(inverse);close_source(output);
 }assert_eq!(original.borrow().get().len(),count);close_source(native);close_source(authored_table);close_source(original);}}}
#[test]
fn native_material_reorder_preserves_original_field_issuers_and_inverse_order(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for case in f["reorder"].as_array().unwrap(){let count=case["count"].as_u64().unwrap()as usize;let from=case["from"].as_u64().unwrap()as usize;let to=case["to"].as_u64().unwrap()as usize;for cut in std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let original=source(received_table(count));let moved=source(sealed_original(original.borrow().project(from,move|table|table.get(from).unwrap())));let removed=source(splice(original.borrow(),None,PersistentSpliceKind::Remove,from,None).unwrap());if let Some(output)=splice(removed.borrow(),Some(moved.borrow()),PersistentSpliceKind::Insert,to,cut){let output=source(output);let mut ranks:Vec<_>=(0..count).collect();let rank=ranks.remove(from);ranks.insert(to,rank);for(i,rank)in ranks.iter().enumerate(){let row=output.borrow().get().get(i).unwrap();let before=original.borrow().get().get(*rank).unwrap();assert_eq!(row.id.as_str(),before.id.as_str());assert!(std::ptr::eq(row.id.get(),before.id.get()));assert!(std::ptr::eq(row.name.get(),before.name.get()));}let inverse_removed=source(splice(output.borrow(),None,PersistentSpliceKind::Remove,to,None).unwrap());let inverse=splice(inverse_removed.borrow(),Some(moved.borrow()),PersistentSpliceKind::Insert,from,None).unwrap();assert_eq!(&inverse,original.borrow().get());drain(inverse);close_source(inverse_removed);close_source(output);}assert_eq!(original.borrow().get().len(),count);close_source(removed);close_source(moved);close_source(original);}}}
#[test]
fn native_material_table_receives_original_order_and_closes_cancelled_frontiers(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for count in f["counts"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;let expected=expected(count,f["prefix"].as_str().unwrap());let total=turns::<Table,DslValue>(||DslValue::from(&expected));let cuts:Vec<_>=std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|c|Some(c.as_u64().unwrap()as usize))).collect();for cut in cuts{
  let original=source(DslValue::from(&expected));let foreign=source(DslValue::from(&expected));let pointer=std::ptr::from_ref(original.borrow().get());let mut receiver=<Table as NativeReceive<DslValue>>::receiver();
  let published=match cut{Some(cut)=>{with_bank(|bank|driver::none(driver::receive_cut(&mut receiver,original.borrow(),bank,BODY,Some((cut as u64).min(total+1))))).unwrap();if receiver.output_ready(){None}else{if cut>0{assert!(receiver.demands(foreign.borrow(),BODY,MAXIMUM).is_err());}None}},None=>with_bank(|bank|driver::receive_cut(&mut receiver,original.borrow(),bank,BODY,None)).unwrap()};
  assert_eq!(std::ptr::from_ref(original.borrow().get()),pointer);
  if let Some(root)=published{assert_eq!(root.len(),count);for i in 0..count{let value=root.get(i).unwrap().to_value();assert_eq!(value.get("id").unwrap().as_str(),expected[i]["id"].as_str());assert_eq!(value.get("name").unwrap().as_str(),expected[i]["name"].as_str());for key in ["e","g","nu","rho"]{if let Some(number)=expected[i].get(key){assert_eq!(value.get(key).unwrap().as_f64().unwrap().to_bits(),number.as_f64().unwrap().to_bits());}}drain(value);}drain(root);}
  with_bank(|bank|driver::close(&mut receiver,bank,BODY));assert!(receiver.terminal_is_empty());let(_,h)=observe(||drop(receiver));assert_eq!(h,(0,0));close_source(original);close_source(foreign);
 }}
}
